import numpy_financial as npf

# Detailed payback analysis
wacc = 0.15
tg = 0.02
tax = 0.21

scenarios = {
    'Bear (Build: organic, slow ramp)': {
        'capex': -70, 'rev': [0, 5, 15, 35, 50, 60],
        'gm': 0.28, 'sga': 0.18, 'note': 'Organic build, lower margins, channel mismatch'
    },
    'Base (Buy: acquisition, $50M)': {
        'capex': -50, 'rev': [0, 10, 30, 50, 60, 70],
        'gm': 0.35, 'sga': 0.15, 'note': 'Acquisition mid-size player, IT channel build'
    },
    'Bull (Partner: OEM fast-ramp)': {
        'capex': -20, 'rev': [0, 15, 40, 60, 80, 100],
        'gm': 0.30, 'sga': 0.12, 'note': 'Partner channel, fast ramp, lower margin'
    }
}

for name, s in scenarios.items():
    fcf = [s['capex']]
    for r in s['rev'][1:]:
        ebit = r * (s['gm'] - s['sga'])
        nopat = ebit - max(0, ebit) * tax
        fcf.append(nopat)

    tv = fcf[5] * (1 + tg) / (wacc - tg)
    npv = sum(fcf[i]/(1+wacc)**i for i in range(6)) + tv/(1+wacc)**5

    fcf_tv = fcf[:]
    fcf_tv[5] += tv
    try:
        irr_val = npf.irr(fcf_tv)
    except:
        irr_val = float('nan')

    # Payback period (undiscounted)
    cum = 0
    payback_yr = None
    for i, f in enumerate(fcf):
        cum += f
        if cum >= 0 and payback_yr is None:
            payback_yr = i
    if payback_yr is None:
        payback_yr = '>5 yrs'

    # Discounted payback
    dcum = 0
    d_payback_yr = None
    for i, f in enumerate(fcf):
        dcum += f / (1+wacc)**i
        if dcum >= 0 and d_payback_yr is None:
            d_payback_yr = i
    if d_payback_yr is None:
        d_payback_yr = '>5 yrs'

    print(f'=== {name} ===')
    print(f'  FCF: {[round(f,2) for f in fcf]}')
    print(f'  TV (undiscounted): {tv:.1f}M | TV (PV): {tv/(1+wacc)**5:.1f}M')
    print(f'  NPV @ 15%: {npv:.2f}M | IRR: {irr_val*100:.1f}%')
    print(f'  Undiscounted payback: {payback_yr} | Discounted payback: {d_payback_yr}')
    print()
"
